window.ScripturaLexicons.LSJ.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1753\" data-lsj-orig-id=\"n1753\" data-lsj-ordinal=\"1776\"><td class=\"greek\">ἀεροσκοπία</td><td>LSJ</td><td>Adivinhação pela observação do céu; em um testemunho pode ser leitura incorreta de ἱεροσκοπία.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1754\" data-lsj-orig-id=\"n1754\" data-lsj-ordinal=\"1777\"><td class=\"greek\">ἀερότεμις</td><td>LSJ</td><td>Explicação etimológica antiga proposta para o nome Ártemis; não etimologia comprovada.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1754a\" data-lsj-orig-id=\"n1754a\" data-lsj-ordinal=\"1778\"><td class=\"greek\">ἀεροτόμος</td><td>LSJ</td><td>Glosa «as aves» (τὰ πετεινά), segundo Cirilo; entrada do suplemento.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1755\" data-lsj-orig-id=\"n1755\" data-lsj-ordinal=\"1779\"><td class=\"greek\">ἀερότονος</td><td>LSJ</td><td>Movido ou impulsionado pelo ar, como uma catapulta.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1756\" data-lsj-orig-id=\"n1756\" data-lsj-ordinal=\"1780\"><td class=\"greek\">ἀεροφόβος</td><td>LSJ</td><td>Que tem medo do ar; termo de descrição médica.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1757\" data-lsj-orig-id=\"n1757\" data-lsj-ordinal=\"1781\"><td class=\"greek\">ἀεροφοίτητος</td><td>LSJ</td><td>Equivalente ao artigo seguinte, relativo ao que vaga no ar; de vento e ave fabulosa.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1758\" data-lsj-orig-id=\"n1758\" data-lsj-ordinal=\"1782\"><td class=\"greek\">ἀερόφοιτος</td><td>LSJ</td><td>Que vagueia, circula ou percorre o ar; forma nominal correlata para astro.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1759\" data-lsj-orig-id=\"n1759\" data-lsj-ordinal=\"1783\"><td class=\"greek\">ἀεροφόρητος</td><td>LSJ</td><td>Sustentado ou transportado pelo ar.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1760\" data-lsj-orig-id=\"n1760\" data-lsj-ordinal=\"1784\"><td class=\"greek\">ἀεροφυής</td><td>LSJ</td><td>Produzido ou nascido do ar, de elemento ou raiz.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1761\" data-lsj-orig-id=\"n1761\" data-lsj-ordinal=\"1785\"><td class=\"greek\">ἀερόχροος</td><td>LSJ</td><td>De coloração semelhante à do ar; equivalente a ἀέρινος na segunda acepção.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1762\" data-lsj-orig-id=\"n1762\" data-lsj-ordinal=\"1786\"><td class=\"greek\">ἀέροψ</td><td>LSJ</td><td>Nome beócio da ave μέροψ, segundo escólio.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1763\" data-lsj-orig-id=\"n1763\" data-lsj-ordinal=\"1787\"><td class=\"greek\">ἀέρρω</td><td>LSJ</td><td>Forma eólica de ἀείρω: levantar, erguer; também retirar ou afastar, como o pensamento.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1764\" data-lsj-orig-id=\"n1764\" data-lsj-ordinal=\"1788\"><td class=\"greek\">ἀερσίλοφος</td><td>LSJ</td><td>De crista elevada, de penacho alto; também de lugares elevados.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1765\" data-lsj-orig-id=\"n1765\" data-lsj-ordinal=\"1789\"><td class=\"greek\">ἀερσίμαχος</td><td>LSJ</td><td>Que desperta ou excita o combate, que incita a luta.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1766\" data-lsj-orig-id=\"n1766\" data-lsj-ordinal=\"1790\"><td class=\"greek\">ἀερσίνοος</td><td>LSJ</td><td>Que eleva a inteligência, revigora o ânimo; também «alegrador» em leitura provável.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1767\" data-lsj-orig-id=\"n1767\" data-lsj-ordinal=\"1791\"><td class=\"greek\">ἀερσιπέτης</td><td>LSJ</td><td>Equivalente a ἀερσιπότης, de voo ou ascensão elevada.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1768\" data-lsj-orig-id=\"n1768\" data-lsj-ordinal=\"1792\"><td class=\"greek\">ἀερσιπόδης</td><td>LSJ</td><td>Equivalente a ἀερσίπους, que levanta alto os pés.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1769\" data-lsj-orig-id=\"n1769\" data-lsj-ordinal=\"1793\"><td class=\"greek\">ἀερσιπόρος</td><td>LSJ</td><td>Que sobe ou vai às alturas.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1770\" data-lsj-orig-id=\"n1770\" data-lsj-ordinal=\"1794\"><td class=\"greek\">ἀερσιπότης</td><td>LSJ</td><td>Que se eleva em grande voo, voa alto.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1771\" data-lsj-orig-id=\"n1771\" data-lsj-ordinal=\"1795\"><td class=\"greek\">ἀερσιπότητος</td><td>LSJ</td><td>Equivalente ao anterior ἀερσιπότης, de voo elevado.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1772\" data-lsj-orig-id=\"n1772\" data-lsj-ordinal=\"1796\"><td class=\"greek\">ἀερσίπους</td><td>LSJ</td><td>Que eleva muito os pés, de passo alto, especialmente de cavalos.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1773\" data-lsj-orig-id=\"n1773\" data-lsj-ordinal=\"1797\"><td class=\"greek\">ἀερσίφρων</td><td>LSJ</td><td>Que eleva e alegra o coração, alentador, especialmente como epíteto de Dioniso.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1774\" data-lsj-orig-id=\"n1774\" data-lsj-ordinal=\"1798\"><td class=\"greek\">ἀερτάζω</td><td>LSJ</td><td>Elevar, erguer, levantar; forma épica ampliada de ἀείρω, com formas verbais documentadas.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1775\" data-lsj-orig-id=\"n1775\" data-lsj-ordinal=\"1799\"><td class=\"greek\">ἀερώδης</td><td>LSJ</td><td>Semelhante ao ar; ligado ao ar, na astrologia; leve e tênue; cheio de ar, de natureza aérea.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n1776\" data-lsj-orig-id=\"n1776\" data-lsj-ordinal=\"1800\"><td class=\"greek\">ἀέρωσις</td><td>LSJ</td><td>Rarefação, diminuição da densidade, inclusive do sangue.</td><td>LSJ</td></tr>";
